-- Executed only by guarded runner against an EMPTY localhost LumenTest_* DB.
-- No production data, DB creation, DROP or DELETE. Fixture names are synthetic.
IF DB_NAME() NOT LIKE 'LumenTest[_]%'
    THROW 51000, 'Only isolated LumenTest DB permitted', 1;
GO
CREATE TABLE dbo.LG_999_99_ORFICHE (
 LOGICALREF INT IDENTITY PRIMARY KEY, FICHENO VARCHAR(40) NOT NULL UNIQUE, JOB INT NOT NULL
);
CREATE TABLE dbo.LG_999_99_ORFLINE (
 LOGICALREF INT IDENTITY PRIMARY KEY,
 ORDFICHEREF INT NOT NULL REFERENCES dbo.LG_999_99_ORFICHE(LOGICALREF), JOB INT NOT NULL
);
CREATE TABLE dbo.LUMEN_TEST_TRIGGER_LOG (ID INT IDENTITY(900000,1) PRIMARY KEY, HEADER_ID INT NOT NULL);
GO
CREATE TRIGGER dbo.LUMEN_TEST_HEADER_TRIGGER ON dbo.LG_999_99_ORFICHE AFTER INSERT AS BEGIN
 INSERT INTO dbo.LUMEN_TEST_TRIGGER_LOG (HEADER_ID) SELECT LOGICALREF FROM inserted;
 SELECT ID AS TRIGGER_ID FROM dbo.LUMEN_TEST_TRIGGER_LOG;
END;
GO
